#!/usr/bin/env node
/**
 * Writes supabase/functions/_shared/schema.generated.ts: the SQL type of every
 * column of every public table, read from supabase/migrations. The Edge
 * Functions' `entities` shim uses it to turn Base44's empty strings into null
 * on uuid/timestamptz/number columns and to drop fields a table does not have.
 *
 *   npm run generate:supabase-schema          # rewrite the file
 *   npm run generate:supabase-schema -- --check   # fail if it is stale (CI)
 *
 * Never edit the generated file by hand.
 */

import process from "node:process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { readMigrationColumns } from "./lib/supabase-migrations.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(root, "supabase", "functions", "_shared", "schema.generated.ts");

const tables = readMigrationColumns(join(root, "supabase", "migrations"));
const lines = [
  "// GENERATED by scripts/generate-supabase-schema.mjs from supabase/migrations.",
  "// Do not edit: run `npm run generate:supabase-schema`.",
  "",
  "export const COLUMN_TYPES: Record<string, Record<string, string>> = {",
];
for (const table of [...tables.keys()].sort()) {
  lines.push(`  ${table}: {`);
  for (const [col, type] of tables.get(table)) lines.push(`    ${col}: '${type}',`);
  lines.push("  },");
}
lines.push("};", "");
const text = lines.join("\n");

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {
    // missing counts as stale
  }
  if (current !== text) {
    console.error("✗ supabase/functions/_shared/schema.generated.ts is stale: run `npm run generate:supabase-schema`.");
    process.exit(1);
  }
  console.log(`✓ schema.generated.ts matches supabase/migrations (${tables.size} tables).`);
} else {
  writeFileSync(OUT, text);
  console.log(`wrote ${OUT} (${tables.size} tables)`);
}
